css:
.dcx,.dcx{margin:0;padding:0;background:#FFFFFF;font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:#202722;-webkit-font-smoothing:antialiased}
.dcx *{box-sizing:border-box}
.dcx h1,.dcx h2,.dcx h3,.dcx p,.dcx ul,.dcx ol,.dcx figure,.dcx dl,.dcx dd{margin:0}
.dcx a{color:#0C4B3B}
.dcx a:hover{color:#08362A}
.dcx button,.dcx input,.dcx select,.dcx textarea{font:inherit;color:inherit}
.dcx :focus-visible{outline:3px solid #FF6347;outline-offset:2px}
.dcx label:has(>input[type=radio]:focus-visible){outline:3px solid #FF6347;outline-offset:2px}
.dcx [data-field]:focus-within{border-color:#0C4B3B !important;box-shadow:0 0 0 3px rgba(12,75,59,.14)}
.dcx [data-field] input:focus-visible,.dcx [data-field] select:focus-visible{outline:none}
.dcx details>summary{list-style:none;cursor:pointer}
.dcx details>summary::-webkit-details-marker{display:none}
.dcx details[open] [data-chev]{transform:rotate(180deg)}
@media (min-width:980px){.dcx [data-sticky]{position:sticky;top:96px}
}
@media (prefers-reduced-motion:reduce){.dcx *{transition:none !important;animation:none !important;scroll-behavior:auto !important}
}
.dcx [data-printonly]{display:none}
@media print{.dcx *{visibility:hidden}
.dcx [data-print],.dcx [data-print] *{visibility:visible}
.dcx [data-print]{position:absolute;left:0;top:0;width:100%;box-shadow:none !important;border:1px solid #999 !important}
.dcx [data-noprint]{display:none !important}
.dcx [data-printonly]{display:block !important}
}

